select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"open_library_id":"OL289798A"},"seq":1,"relation":"authors","after_row":{"id":987356001,"name":"Gerrit Komrij","open_library_id":"OL289798A"},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL15253510W"},"seq":2,"relation":"works","after_row":{"id":987156001,"title":"Slechte kritieken gaan nooit verloren, goede ook niet, sinds kort","cover_id":null,"author_id":969300005,"work_type":"collection","source_type":"open_library","open_library_id":"OL15253510W","first_publish_year":1993,"native_identity_key":"nlscale:20261102:ol:OL15253510W"},"before_row":null},{"key":{"open_library_edition_id":"OL1492958M"},"seq":3,"relation":"editions","after_row":{"id":987256001,"title":"Slechte kritieken gaan nooit verloren, goede ook niet, sinds kort","isbn_10":null,"isbn_13":"9789023433088","work_id":987156001,"cover_id":null,"language":"dut","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL1492958M"},"before_row":null},{"key":{"work_id":987156001,"language":"nl"},"seq":4,"relation":"catalog_work_descriptions","after_row":{"text":"In dit korte boekje reageert Willem Frederik Hermans op de manier waarop literaire teksten en kritieken worden bewaard en uitgegeven. Aanleiding is een lezing bij de presentatie van LiteROM, de verzameling oudere boekrecensies. Zijn aandacht gaat vooral uit naar een nieuwe historisch-kritische editie van Multatuli’s Max Havelaar. Hermans vergelijkt tekstkeuzes en correcties en bestrijdt de waardering voor die uitgave. De bundel bevat daarnaast een afzonderlijke bijdrage over dezelfde editie, met de polemische inzet van een betrokken lezer.","work_id":987156001,"evidence":[{"note":"Separate1993printedvolume containing LiteROMlecture plus MaxHavelaar-edition polemic, notgenericreviewcollection. ExactDutchPaperback9789023433088, DBNLbibliography gives sewnpaperback.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibli